function distinctSequences(n) {
  const MOD = 1e9 + 7;
  if (n === 1) {
    return 6;
  }
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  let dp = Array.from({ length: 7 }, () => new Array(7).fill(0));
  for (let prev = 1; prev <= 6; prev++) {
    for (let last = 1; last <= 6; last++) {
      if (prev !== last && gcd(prev, last) === 1) {
        dp[prev][last] = 1;
      }
    }
  }
  for (let roll = 3; roll <= n; roll++) {
    const next = Array.from({ length: 7 }, () => new Array(7).fill(0));
    for (let prev = 1; prev <= 6; prev++) {
      for (let last = 1; last <= 6; last++) {
        for (let value = 1; value <= 6; value++) {
          if (value !== prev && value !== last && gcd(last, value) === 1) {
            next[last][value] = (next[last][value] + dp[prev][last]) % MOD;
          }
        }
      }
    }
    dp = next;
  }
  let total = 0;
  for (let prev = 1; prev <= 6; prev++) {
    for (let last = 1; last <= 6; last++) {
      total = (total + dp[prev][last]) % MOD;
    }
  }
  return total;
}

