function distinctSequences(n) {
  // Extend sequences one roll at a time, grouped by their last (up to) two rolls written as a string,
  // checking each rule directly. BigInt counts keep the arithmetic exact before the final modulo.
  const MOD = 1000000007n;
  const gcd = (a, b) => { while (b) [a, b] = [b, a % b]; return a; };
  let counts = new Map([['', 1n]]);
  for (let step = 0; step < n; step++) {
    const next = new Map();
    for (const [tail, count] of counts) {
      const recent = tail ? tail.split(',').map(Number) : [];
      for (let face = 1; face <= 6; face++) {
        if (recent.includes(face)) continue;
        if (recent.length && gcd(recent[recent.length - 1], face) !== 1) continue;
        const key = [...recent, face].slice(-2).join(',');
        next.set(key, ((next.get(key) ?? 0n) + count) % MOD);
      }
    }
    counts = next;
  }
  let total = 0n;
  for (const count of counts.values()) total += count;
  return Number(total % MOD);
}

